upstream mcp_fleet {
  ip_hash;
  server mcp-instance-1:8080;
  server mcp-instance-2:8080;
  server mcp-instance-3:8080;
}

server {
  location /mcp/ {
    proxy_pass http://mcp_fleet;
    proxy_set_header X-Session-Id $http_x_session_id;
  }
}

function pickInstance(sessionId, instances) {
  let hash = 0;
  for (let i = 0; i < sessionId.length; i++) {
    hash = (hash * 31 + sessionId.charCodeAt(i)) >>> 0;
  }
  return instances[hash % instances.length];
}

const sessions = new Map();

function handleRequest(sessionId, message) {
  const session = sessions.get(sessionId);
  if (!session) {
    return { error: 'unknown session' };
  }
  return processMessage(session, message);
}

const redis = require('redis').createClient();

async function loadSession(sessionId) {
  const raw = await redis.get('session:' + sessionId);
  return raw ? JSON.parse(raw) : null;
}

async function saveSession(sessionId, session) {
  await redis.set('session:' + sessionId, JSON.stringify(session), { EX: 3600 });
}

async function handleRequest(sessionId, message) {
  const session = await loadSession(sessionId);
  if (!session) return { error: 'unknown session' };
  const result = processMessage(session, message);
  await saveSession(sessionId, session);
  return result;
}

async function createSession(sessionId) {
  const session = { createdAt: Date.now(), toolCalls: [] };
  await saveSession(sessionId, session);
  return session;
}
